processor-info.script:

			String cmd = input.getText("cmd");

			if(cmd.equals("GET_CORP_LIST"))
            {
				String srch_text = input.getText("title");

	            StringBuffer addWhere = new StringBuffer();

	            if ( srch_text!=null && !srch_text.equals("") )
	            {
	                addWhere.append("AND company like '%" + srch_text + "%' ");
	            }

	            String search_gbn_hcode = input.getText("search_gbn_hcode");

				if( "20".equals(search_gbn_hcode))
					addWhere.append(" AND hcode in ('10','20','30') " );
				else if( !"".equals(search_gbn_hcode))
					addWhere.append(" AND hcode = '" + search_gbn_hcode + "'" );


	            input.put("addWhere", addWhere.toString() );
	        }    

			executeSQL(cmd, connection, input, output);
